            new Quote { Id = "https://en.wikiquote.org/wiki/Leo_Tolstoy", Text = "In all history there is no war which was not hatched by the governments, the governments alone, independent of the interests of the people, to whom war is always pernicious even when successful.", Author = "Leo Tolstoy" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Leo_Tolstoy", Text = "Government is violence, Christianity is meekness, non-resistance, love. And, therefore, government cannot be CHRISTIAN, and a man who wishes to be a Christian must not serve government.", Author = "Leo Tolstoy" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Leo_Tolstoy", Text = "Everyone thinks of changing the world, but no one thinks of changing himself.", Author = "Leo Tolstoy" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Leo_Tolstoy", Text = "Every one who has a heart and eyes sees that you, working men, are obliged to pass your lives in want and in hard labor, which is useless to you, while other men, who do not work, enjoy the fruits of your labor—that you are the slaves of these men, and that this ought not to exist.", Author = "Leo Tolstoy" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Leo_Tolstoy", Text = "All violence consists in some people forcing others, under threat of suffering or death, to do what they do not want to do.", Author = "Leo Tolstoy" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Leo_Tolstoy", Text = "God is the infinite All. Man is only a finite manifestation of Him.", Author = "Leo Tolstoy" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Leo_Tolstoy", Text = "The truth is that the State is a conspiracy designed not only to exploit, but above all to corrupt its citizens ... Henceforth, I shall never serve any government anywhere.", Author = "Leo Tolstoy" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Leo_Tolstoy", Text = "Science is meaningless because it gives no answer to our question, the only question important for us: 'what shall we do and how shall we live'", Author = "Leo Tolstoy" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Leo_Tolstoy", Text = "There is only one enduring happiness in life—to live for others.", Author = "Leo Tolstoy" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Leo_Tolstoy", Text = "Seize the moments of happiness, love and be loved! That is the only reality in the world, all else is folly. It is the one thing we are interested in here.", Author = "Leo Tolstoy" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Leo_Tolstoy", Text = "You will die — and it will all be over. You will die and find out everything — or cease asking.", Author = "Leo Tolstoy" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Leo_Tolstoy", Text = "The only thing that we know is that we know nothing — and that is the highest flight of human wisdom.", Author = "Leo Tolstoy" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Leo_Tolstoy", Text = "Every action of theirs, that seems to them an act of their own free will, is in an historical sense not free at all, but in bondage to the whole course of previous history, and predestined from all eternity.", Author = "Leo Tolstoy" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Leo_Tolstoy", Text = "A king is history's slave.", Author = "Leo Tolstoy" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Leo_Tolstoy", Text = "Everything comes in time to him who knows how to wait.", Author = "Leo Tolstoy" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Leo_Tolstoy", Text = "The strongest of all warriors are these two — Time and Patience.", Author = "Leo Tolstoy" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Leo_Tolstoy", Text = "Love hinders death. Love is life. All, everything that I understand, I understand only because I love. Everything is, everything exists, only because I love. Everything is united by it alone. Love is God, and to die means that I, a particle of love, shall return to the general and eternal source.", Author = "Leo Tolstoy" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Leo_Tolstoy", Text = "To love life is to love God. Harder and more blessed than all else is to love this life in one's sufferings, in undeserved sufferings.", Author = "Leo Tolstoy" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Leo_Tolstoy", Text = "For us, with the rule of right and wrong given us by Christ, there is nothing for which we have no standard. And there is no greatness where there is not simplicity, goodness, and truth.", Author = "Leo Tolstoy" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Leo_Tolstoy", Text = "Pure and complete sorrow is as impossible as pure and complete joy.", Author = "Leo Tolstoy" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Leo_Tolstoy", Text = "History is the life of nations and of humanity. To seize and put into words, to describe directly the life of humanity or even of a single nation, appears impossible.", Author = "Leo Tolstoy" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Leo_Tolstoy", Text = "All happy families resemble one another, each unhappy family is unhappy in its own way.", Author = "Leo Tolstoy" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Leo_Tolstoy", Text = "He stepped down, trying not to look long at her, as if she were the sun, yet he saw her, like the sun, even without looking.", Author = "Leo Tolstoy" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Leo_Tolstoy", Text = "\"Respect was invented to cover the empty place where love should be.\"", Author = "Leo Tolstoy" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Leo_Tolstoy", Text = "Reason has discovered the struggle for existence and the law that I must throttle all those who hinder the satisfaction of my desires. That is the deduction reason makes. But the law of loving others could not be discovered by reason, because it is unreasonable.", Author = "Leo Tolstoy" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Leo_Tolstoy", Text = "There is one evident, indubitable manifestation of the Divinity, and that is the laws of right which are made known to the world through Revelation.", Author = "Leo Tolstoy" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Leo_Tolstoy", Text = "My reason will still not understand why I pray, but I shall still pray, and my life, my whole life, independently of anything that may happen to me, is every moment of it no longer meaningless as it was before, but has an unquestionable meaning of goodness with which I have the power to invest it.'", Author = "Leo Tolstoy" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Leo_Tolstoy", Text = "Learn 'What dwells in man, What is not given to man', and 'What men live by'. When thou hast learnt these things, thou shalt return to heaven.", Author = "Leo Tolstoy" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Leo_Tolstoy", Text = "I looked up, and did not recognize the same man: before, I had seen death in his face; but now he was alive, and I recognized in him the presence of God.", Author = "Leo Tolstoy" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Leo_Tolstoy", Text = "And I understood that in man dwells Love! I was glad that God had already begun to show me what He had promised, and I smiled for the first time.", Author = "Leo Tolstoy" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Leo_Tolstoy", Text = "It is not given to man to know his own needs.", Author = "Leo Tolstoy" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Leo_Tolstoy", Text = "And the angel's body was bared, and he was clothed in light so that eye could not look on him; and his voice grew louder, as though it came not from him but from heaven above. And the angel said: I have learnt that all men live not by care for themselves, but by love.", Author = "Leo Tolstoy" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Leo_Tolstoy", Text = "It was not given to the mother to know what her children needed for their life. Nor was it given to the rich man to know what he himself needed. Nor is it given to any man to know whether, when evening comes, he will need boots for his body or slippers for his corpse.", Author = "Leo Tolstoy" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Leo_Tolstoy", Text = "I have now understood that though it seems to men that they live by care for themselves, in truth it is love alone by which they live. He who has love, is in God, and God is in him, for God is love.", Author = "Leo Tolstoy" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Leo_Tolstoy", Text = "Quite often a man goes on for years imagining that the religious teaching that had been imparted to him since childhood is still intact, while all the time there is not a trace of it left in him.", Author = "Leo Tolstoy" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Leo_Tolstoy", Text = "One can only live while one is intoxicated with life; as soon as one is sober it is impossible not to see that it is all a mere fraud and a stupid fraud!", Author = "Leo Tolstoy" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Leo_Tolstoy", Text = "It is possible to live only as long as life intoxicates us; once we are sober we cannot help seeing that it is all a delusion, a stupid delusion.", Author = "Leo Tolstoy" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Leo_Tolstoy", Text = "The only absolute knowledge attainable by man is that life is meaningless.", Author = "Leo Tolstoy" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Leo_Tolstoy", Text = "For man to be able to live he must either not see the infinite, or have such an explanation of the meaning of life as will connect the finite with the infinite.", Author = "Leo Tolstoy" },
        };
